    {
      "why": "Publisher-facing adtech with flat card grids, metric-display typography at display scale, and low-shadow surfaces",
      "business": "Primer.io"
    },
    {
      "why": "Real-time audience data UI with warm off-white backgrounds, monochrome logo strips, and stat-as-hero visual pattern",
      "business": "Chartbeat"
    }
  ]
}

