  {
    "name": "Primary Filled CTA Button",
    "role": "Highest-priority action: 'Get Started', 'Try Free'",
    "description": "Background #1c1a17, text white (#ffffff), border-radius 48px, padding 7px 12px. At nav scale: compact pill. The near-black fill distinguishes it from the orange (#ff6020) used for announcement CTAs \u2014 nav primary action is authoritative, not urgent."
  },
  {
    "name": "Outlined Ghost Button",
    "role": "Secondary actions: 'Explore Marketplace', 'Sign In'",
    "description": "Background transparent, text #1c1a17 at 72% opacity, border 1px solid rgba(0,0,0,0.12), border-radius 20px, padding 8px 16px. The semi-transparent text color against the near-white background reads as intentionally recessive \u2014 draws eye to the filled CTA without disappearing."
  },
  {
    "name": "White Card Button / Chip",
    "role": "Clickable panel triggers, demo tab selectors",
    "description": "Background #ffffff, text uses accent colors (#777eff), border 1px solid #f1f1f1, border-radius 12px, padding 24px. These double as both filter pills and interactive card surfaces in the product demo UI."
  },
  {
    "name": "Filter Pill",
    "role": "Publisher directory category filters: 'All 1291', 'Arts & Entertainment'",
    "description": "Background transparent, border 1px solid rgba(0,0,0,0.12), border-radius 999px, padding 7px 12px, text Inter 400 14px #1c1a17 at 72% opacity. Active state not fully specified but implied by filled #1c1a17 background."
  },
  {
    "name": "Content Card (Light)",
    "role": "Publisher directory listing cards, feature explanation cards",
    "description": "Background #fafafa, border-radius 10px, no shadow, no border. Inner content uses Inter 400 14px body text at #5a5957, bold publisher name at #1c1a17 Inter 600 15px. Bottom row shows colored metric badges (Mint Pulse green for 'High AI Traffic', orange for revenue)."
  },
  {
    "name": "Dark Stat Card",
    "role": "Trust/social proof hero metric, 'Trusted by publishers' card",
    "description": "Background radial-gradient(81% 66% at 1.8% 1.1%, #545454 0%, #1c1a17 100%), border-radius 10px, white text. Headline Inter 700 at display size, sub-label Inter 400 14px white at 70% opacity. This single dark card anchors the 4-column stats grid."
  },
  {
    "name": "Metric Stat Cell",
    "role": "Numerical KPI display: '$0M+ Paid to Publishers', '0M+ AI Reach'",
    "description": "Background #fafafa, border-radius 10px, no shadow. Label Inter 400 14px #7e7d7b at top, numeral Mona Sans 700 40-48px #1c1a17 with -0.03em tracking. Compact padding 24px inside the cell."
  },
  {
    "name": "Category Badge",
    "role": "Taxonomy tags on publisher cards: 'Internet & Telecom', 'en', 'Arts & Entertainment'",
    "description": "Background #fafafa, text Inter 400 12px #52525b, border-radius 6px, padding 4px 10px. Stack horizontally with 4px gap. No border \u2014 the background/surface contrast provides definition."
  },
  {
    "name": "Announcement Bar",
    "role": "Top-of-page event promotion strip",
    "description": "Full-bleed background #000000, centered Inter 400 14px white body text, orange (#ff6020) 'Schedule a meeting' text link at right. Fixed height ~36px. The only full-bleed black element on an otherwise light page \u2014 immediately commands attention."
  },
  {
    "name": "Top Navigation Bar",
    "role": "Sticky site navigation",
    "description": "Background #ffffff, border-bottom 1px solid #f1f1f1, height ~60px. Left: Mona Sans wordmark 'panxo' + Inter 500 11px 'AI' label. Center: Inter 500 14px nav links at #5a5957 with chevron dropdowns. Right: 'Sign In' ghost text, 'Get Started' pill #1c1a17 48px radius. 'Early Access' badge uses #10b981 green with Inter 600 10px uppercase tracking."
  },
  {
    "name": "Product Demo UI Card",
    "role": "Hero section interactive visualization of AI traffic classification",
    "description": "White background card with 12-20px radius, shadow: rgba(95,99,106,0.08) 0 0 0 1px + rgba(43,43,48,0.1) 0 1px 4px. Interior tabs use the White Card Button / Chip pattern. Body text shows inline color-coded classifications: #777eff for AI source tags, #731fff for segment labels, #ff6020 for CPM values, #05933b for confidence percentages."
  },
  {
    "name": "Spectrum Gradient Panel",
    "role": "Hero visualization backdrop, atmospheric visual section divider",
    "description": "linear-gradient(90deg, #10b981 0%, #a855f7 50%, #f59e0b 100%) applied to large contained panels, border-radius 15px or full-bleed. This is the site's single high-chroma element \u2014 all other color is data-functional."
  },
  {
    "name": "Trust Logo Strip",
    "role": "Social proof publisher logos: Business Insider, Yahoo Finance, Investing.com",
    "description": "Full-width horizontal scroll on a white background. Logos rendered in grayscale (#000000 or desaturated), Inter-weight-matched, no borders or cards. Equal visual weight across brands \u2014 no featured positioning."
  }
]
